SELECT version, description, success, UNIX_TIMESTAMP(installed_on) AS installed_epoch FROM crypto_ai.flyway_schema_history WHERE version IN ('103','104','105','106','107','108','109','110','111') ORDER BY installed_rank;
SELECT id, reference_signal_id, evaluation_path, UNIX_TIMESTAMP(evaluated_at) AS eval_epoch, replay_mode, five_minute_signal_id, five_minute_raw_decision, five_minute_effective_decision, five_minute_data_quality_valid, one_hour_signal_id, one_hour_raw_decision, one_hour_effective_decision, one_hour_data_quality_valid, assessment_band, max_initial_percent, legacy_veto_result, final_result FROM crypto_ai.buy_htf_assessment_audit WHERE reference_signal_id IN (156723,159408,165412,165415,167668,171589,176710) ORDER BY reference_signal_id, evaluated_at LIMIT 60;